import Business
import Domain
import Foundation
import Logging
import Observation

@Observable
@MainActor
public final class SearchViewModel {
    public var searchText = "" {
        didSet { scheduleSearch() }
    }

    public var meetings: [RecordingMetadata] = []
    public private(set) var searchResults: [RecordingMetadata] = []
    public private(set) var searchError: UserFacingError?

    private let searchUseCase: SearchRecordingsUseCase?
    private var searchTask: Task<Void, Never>?
    private let logger = AppLogger.for(category: "SearchViewModel")

    public init(searchUseCase: SearchRecordingsUseCase? = nil) {
        self.searchUseCase = searchUseCase
    }

    public var filteredMeetings: [RecordingMetadata] {
        let trimmed = searchText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return meetings }
        guard searchUseCase != nil else { return meetings }
        return searchResults
    }

    private func scheduleSearch() {
        searchTask?.cancel()
        let trimmed = searchText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, let useCase = searchUseCase else {
            searchResults = []
            searchError = nil
            return
        }
        searchTask?.cancel()
        searchTask = Task { @MainActor [weak self] in
            // Clear stale error before starting the new search attempt
            self?.searchError = nil
            do {
                try await Task.sleep(for: .milliseconds(300))
            } catch { return }
            guard let self else { return }
            do {
                let summaries = try await useCase.search(query: trimmed)
                let matchingIDs = Set(summaries.map(\.id))
                self.searchResults = self.meetings.filter { matchingIDs.contains($0.id) }
                self.searchError = nil
            } catch let error as UserFacingError {
                self.searchResults = []
                self.searchError = error
            } catch {
                self.searchResults = []
                logger.error("Search failed with unexpected error: \(error, privacy: .private)")
                self.searchError = StorageError.searchFailed(underlying: error as? any Error & Sendable)
            }
        }
    }
}

