/// Summarization engine backed by Apple's on-device Foundation Models framework.
///
/// Uses the system ~3B language model available on macOS 26+. Apple manages the
/// process lifetime, memory, and GPU scheduling entirely — no Metal memory
/// management or model download required. Structured output via `@Generable`.
@available(macOS 26.0, *)
public actor AppleFoundationModelsPlugin: SummarizationEngine {
    private static let modelId = ModelID("apple/foundation-models")

    private let logger = AppLogger.for(category: "FoundationModels")

    public init() {}

    // MARK: - SummarizationEngine

    public func loadModel(_: SummaryConfig) async throws {
        // Foundation Models loads automatically — no explicit model management needed.
        logger.info("AppleFoundationModelsPlugin: system model managed by OS, no load step required")
    }

    public func isReady() async -> Bool {
        true
    }

    public func generate(prompt: String) async throws -> String {
        let session = LanguageModelSession()

        do {
            let output: String = try await withThrowingTaskGroup(of: String.self) { group in
                group.addTask {
                    let r = try await session.respond(to: prompt)
                    return r.content
                }
                group.addTask {
                    try await Task.sleep(for: TimeoutConfig.foundationModelsInference)
                    throw SummarizationError.generationFailed(underlying: nil)
                }
                guard let first = try await group.next() else {
                    throw SummarizationError.generationFailed(underlying: nil)
                }
                group.cancelAll()
                return first
            }
            return output
        } catch {
            throw SummarizationError.generationFailed(underlying: error)
        }
    }

