// MARK: - Data helpers for WAV generation

private extension Data {
    mutating func appendLE16(_ v: UInt16) {
        var le = v.littleEndian
        Swift.withUnsafeBytes(of: &le) { append(contentsOf: $0) }
    }
    mutating func appendLE32(_ v: UInt32) {
        var le = v.littleEndian
        Swift.withUnsafeBytes(of: &le) { append(contentsOf: $0) }
    }
}

// MARK: - Helpers

/// Resolves the Tests/Fixtures/ directory relative to this source file at compile time.
private func fixturesDirectory() -> URL {
    URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent() // Infrastructure/
        .deletingLastPathComponent() // Unit/
        .deletingLastPathComponent() // Tests/
        .appendingPathComponent("Fixtures")
}

private func fixtureURL(named filename: String) -> URL {
    fixturesDirectory().appendingPathComponent(filename)
}

/// Generates a minimal valid 44100 Hz mono 16-bit PCM WAV file and writes it to a temp path.
/// Returns the URL. Caller is responsible for cleanup (use `defer { try? FileManager.default.removeItem(at: url) }`).
private func makeWAVFixture(durationSeconds: Int = 2, sampleRate: Int = 44100) throws -> URL {
    let sampleCount = durationSeconds * sampleRate
    let dataBytes = sampleCount * MemoryLayout<Int16>.size
    let fileSize = 44 + dataBytes

    var wav = Data(capacity: fileSize)

    // RIFF header
    wav.append(contentsOf: "RIFF".utf8)
    wav.appendLE32(UInt32(fileSize - 8))
    wav.append(contentsOf: "WAVE".utf8)

    // fmt chunk: PCM, 1 channel, 44100 Hz, 16-bit
    wav.append(contentsOf: "fmt ".utf8)
    wav.appendLE32(16)          // chunk size
    wav.appendLE16(1)           // PCM
    wav.appendLE16(1)           // mono
    wav.appendLE32(UInt32(sampleRate))
    wav.appendLE32(UInt32(sampleRate * 2)) // byte rate
    wav.appendLE16(2)           // block align
    wav.appendLE16(16)          // bits per sample

    // data chunk: silence (all zeros = valid normalized samples)
    wav.append(contentsOf: "data".utf8)
    wav.appendLE32(UInt32(dataBytes))
    wav.append(Data(count: dataBytes))

    let url = FileManager.default.temporaryDirectory
        .appendingPathComponent("test-tone-\(durationSeconds)s-\(UUID().uuidString).wav")
    try wav.write(to: url)
    return url
}

private func makeTemporaryFile(bytes: Data) throws -> URL {
    let tempURL = FileManager.default.temporaryDirectory
        .appendingPathComponent("AudioFileLoaderTests-\(UUID().uuidString).wav")
    try bytes.write(to: tempURL)
    return tempURL
}

