    @Test("MeetingAppEvent.launched is Equatable")
    func launchedEquatable() {
        let a = MeetingAppEvent.launched(bundleId: "us.zoom.xos", name: "Zoom")
        let b = MeetingAppEvent.launched(bundleId: "us.zoom.xos", name: "Zoom")
        #expect(a == b)
