    @Test("file smaller than 44 bytes throws TranscriptionError.audioTooShort")
    func truncatedFileThrowsAudioTooShort() async throws {
        let loader = AudioFileLoader()
        // 20 bytes — well under the 44-byte WAV header threshold
        let truncatedData = Data(repeating: 0x00, count: 20)
        let tempURL = try makeTemporaryFile(bytes: truncatedData)
        defer { try? FileManager.default.removeItem(at: tempURL) }

