import Domain
import Foundation
import FoundationModels
import Logging
import Utilities

/// Summarization engine backed by Apple's on-device Foundation Models framework.
///
/// Uses the system ~3B language model available on macOS 26+. Apple manages the
/// process lifetime, memory, and GPU scheduling entirely — no Metal memory
/// management or model download required. Structured output via `@Generable`.
@available(macOS 26.0, *)
public actor AppleFoundationModelsPlugin: SummarizationEngine {
    private static let modelId = ModelID("apple/foundation-models")

    private let logger = AppLogger.for(category: "FoundationModels")

    public init() {}

    // MARK: - SummarizationEngine

    public func loadModel(_: SummaryConfig) async throws {
        // Foundation Models loads automatically — no explicit model management needed.
        logger.info("AppleFoundationModelsPlugin: system model managed by OS, no load step required")
    }

    public func isReady() async -> Bool {
        true
    }

    public func generate(prompt: String) async throws -> String {
        let session = LanguageModelSession()

        do {
            let output: String = try await withThrowingTaskGroup(of: String.self) { group in
                group.addTask {
                    let r = try await session.respond(to: prompt)
                    return r.content
                }
                group.addTask {
                    try await Task.sleep(for: TimeoutConfig.foundationModelsInference)
                    throw SummarizationError.generationFailed(underlying: nil)
                }
                guard let first = try await group.next() else {
                    throw SummarizationError.generationFailed(underlying: nil)
                }
                group.cancelAll()
                return first
            }
            return output
        } catch {
            throw SummarizationError.generationFailed(underlying: error)
        }
    }

    public func summarize(
        transcript: String, speakers: [String], meetingType: MeetingType
    ) async throws -> MeetingSummary {
        logger.info("CHECKPOINT C: building Foundation Models prompt — \(transcript.count, privacy: .public) chars")

        let session = LanguageModelSession()
        let prompt = buildPrompt(transcript: transcript, speakers: speakers, meetingType: meetingType)

        // LanguageModelSession.Response is not Sendable, so withTimeout() won't work
        // directly. Race a task-group inference leg against a timeout leg; extract
        // .content (Sendable) inside the task before crossing the group boundary.
        logger.info("CHECKPOINT D: calling Foundation Models respond()")
        let startedAt = Date()
        do {
            let output: FoundationModelsSummaryOutput = try await withThrowingTaskGroup(
                of: FoundationModelsSummaryOutput.self
            ) { group in
                group.addTask {
                    let r = try await session.respond(to: prompt, generating: FoundationModelsSummaryOutput.self)
                    return r.content
                }
                group.addTask {
                    try await Task.sleep(for: TimeoutConfig.foundationModelsInference)
                    throw SummarizationError.generationFailed(underlying: nil)
                }
                guard let first = try await group.next() else {
                    throw SummarizationError.generationFailed(underlying: nil)
                }
                group.cancelAll()
                return first
            }
            let elapsed = Date().timeIntervalSince(startedAt)
            logger
                .info(
                    // swiftlint:disable:next line_length
                    "CHECKPOINT F: Foundation Models responded in \(elapsed, format: .fixed(precision: 1), privacy: .public)s"
                )
            return output.toMeetingSummary(
                modelId: Self.modelId,
                processingTime: elapsed,
                generatedAt: startedAt
            )
        } catch {
            let errDesc = String(reflecting: error)
            logger.error("Foundation Models generation failed: \(errDesc, privacy: .private)")
            throw SummarizationError.generationFailed(underlying: error)
        }
    }

    // MARK: - Prompt

    private func buildPrompt(transcript: String, speakers: [String], meetingType: MeetingType) -> String {
        // @Generable structured output doesn't support per-meetingType prompt dispatch yet
        if meetingType != SummaryConfig.default.meetingType {
            // swiftlint:disable:next line_length
            logger.info("meetingType=\(meetingType.rawValue, privacy: .public) ignored — Foundation Models uses generic prompt")
        }
        return AppleFoundationModelsPrompts.buildPrompt(transcript: transcript, speakers: speakers)
    }
}

// MARK: - Generable output DTO

@available(macOS 26.0, *)
@Generable
private struct FoundationModelsSummaryOutput {
    @Guide(description: "2-3 sentence TL;DR of the meeting") var summary: String
    @Guide(description: "Key decisions made") var decisions: [String]
    @Guide(description: "Action items with owner if mentioned") var actionItems: [FoundationModelsActionItem]
    @Guide(description: "Main topics discussed") var topics: [String]
    @Guide(description: "Unresolved questions or open issues") var openQuestions: [String]

    func toMeetingSummary(modelId: ModelID, processingTime: TimeInterval, generatedAt: Date) -> MeetingSummary {
        MeetingSummary(
            summary: summary,
            decisions: decisions,
            actionItems: actionItems.map { ActionItem(description: $0.description, assignee: $0.assignee) },
            topics: topics,
            openQuestions: openQuestions,
            generatedAt: generatedAt,
            modelId: modelId,
            processingTime: processingTime
        )
    }
}

@available(macOS 26.0, *)
@Generable
private struct FoundationModelsActionItem {
    @Guide(description: "What needs to be done") var description: String
    @Guide(description: "Person responsible, or nil") var assignee: String?
}

