import Domain
import Foundation
@testable import AudioInfrastructure
import Testing

@Suite("AudioSessionDetector")
struct AudioSessionDetectorTests {
    @Test("conforms to MeetingDetector")
    func conformsToProtocol() {
        let detector = AudioSessionDetector(
            startDebounce: 3.0,
            stopDebounce: 10.0,
            autoListen: false
        )
        let _: any MeetingDetector = detector
    }

    @Test("isActive returns false initially")
    func initiallyInactive() async {
        let detector = AudioSessionDetector(startDebounce: 3.0, stopDebounce: 10.0, autoListen: false)
        let active = await detector.isActive()
        #expect(!active)
    }

    @Test("simulateActivation followed by debounce emits meetingStarted")
    func activationEmitsStart() async throws {
        let detector = AudioSessionDetector(startDebounce: 0.1, stopDebounce: 0.1, autoListen: false)
        let stream = detector.events()

        await detector.simulateActivation()
        try await Task.sleep(for: .milliseconds(200))

        var events: [MeetingDetectorEvent] = []
        for await event in stream {
            events.append(event)
            if events.count >= 1 { break }
        }

        #expect(events.contains(.meetingStarted(context: nil)))
    }

    @Test("simulateDeactivation after activation emits meetingStopped")
    func deactivationEmitsStop() async throws {
        let detector = AudioSessionDetector(startDebounce: 0.05, stopDebounce: 0.05, autoListen: false)
        let stream = detector.events()

        await detector.simulateActivation()
        try await Task.sleep(for: .milliseconds(100))
        await detector.simulateDeactivation()
        try await Task.sleep(for: .milliseconds(100))

        var events: [MeetingDetectorEvent] = []
        for await event in stream {
            events.append(event)
            if events.count >= 2 { break }
        }

        #expect(events == [.meetingStarted(context: nil), .meetingStopped])
    }

    @Test("brief activation within debounce window does not emit")
    func briefActivationSuppressed() async throws {
        let detector = AudioSessionDetector(startDebounce: 0.5, stopDebounce: 0.5, autoListen: false)

        await detector.simulateActivation()
        try await Task.sleep(for: .milliseconds(50))
        await detector.simulateDeactivation()
        try await Task.sleep(for: .milliseconds(100))

        let active = await detector.isActive()
        #expect(!active, "brief activation within debounce should not trigger")
    }

    @Test("debounce values are configurable")
    func configurableDebounce() {
        let detector = AudioSessionDetector(startDebounce: 5.0, stopDebounce: 15.0, autoListen: false)
        #expect(detector.startDebounce == 5.0)
        #expect(detector.stopDebounce == 15.0)
    }
}

// MARK: - Slice C+D: C1 + D2 source inspection

extension AudioSessionDetectorTests {
    private func source() throws -> String {
        let r = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent()
            .deletingLastPathComponent().deletingLastPathComponent()
        return try String(
            contentsOfFile: r
                .appendingPathComponent("Sources/Infrastructure/Audio/AudioSessionDetector.swift").path,
            encoding: .utf8
        )
    }

    @Test func `AudioSessionDetector events uses makeStream not Task-in-closure`() throws {
        let src = try source()
        #expect(!src.contains("Task { await self.setContinuation"), "events() must use makeStream() at init")
    }

    @Test func `AudioSessionListenerBox has NSLock`() throws {
        let src = try source()
        #expect(src.contains("NSLock"), "AudioSessionListenerBox must use NSLock to serialize mutations")
    }
}

import Domain
import Foundation
@testable import AudioInfrastructure
import Testing

@Suite("AudioSessionDetector — CoreAudio & SelfRecordingStateProvider")
struct AudioSessionDetectorCoreAudioTests {
    // MARK: - SAFE-001: Self-recording suppression

    @Test("SAFE-001: activation suppressed when isSelfRecording returns true")
    func activationSuppressedWhenSelfRecording() async throws {
        let provider = MockSelfRecordingStateProvider(recording: true)
        let detector = AudioSessionDetector(
            startDebounce: 0.05,
            stopDebounce: 0.05,
            selfRecordingProvider: provider,
            autoListen: false
        )

        await detector.simulateActivation()
        try await Task.sleep(for: .milliseconds(200))

        // meetingActive must remain false — suppressed by self-recording
        let active = await detector.isActive()
        #expect(!active, "SAFE-001: meetingActive must remain false when THE RECORD is self-recording")
    }

    @Test("SAFE-001: activation proceeds when isSelfRecording returns false")
    func activationProceedsWhenNotSelfRecording() async throws {
        let provider = MockSelfRecordingStateProvider(recording: false)
        let detector = AudioSessionDetector(
            startDebounce: 0.05,
            stopDebounce: 0.05,
            selfRecordingProvider: provider,
            autoListen: false
        )
        let stream = detector.events()

