import Domain
import Foundation
@testable import AudioInfrastructure
import Testing

@Suite("AudioSessionDetector — CoreAudio & SelfRecordingStateProvider")
struct AudioSessionDetectorCoreAudioTests {
    // MARK: - SAFE-001: Self-recording suppression

    @Test("SAFE-001: activation suppressed when isSelfRecording returns true")
    func activationSuppressedWhenSelfRecording() async throws {
        let provider = MockSelfRecordingStateProvider(recording: true)
        let detector = AudioSessionDetector(
            startDebounce: 0.05,
            stopDebounce: 0.05,
            selfRecordingProvider: provider,
            autoListen: false
        )

        await detector.simulateActivation()
        try await Task.sleep(for: .milliseconds(200))

        // meetingActive must remain false — suppressed by self-recording
        let active = await detector.isActive()
        #expect(!active, "SAFE-001: meetingActive must remain false when THE RECORD is self-recording")
    }

    @Test("SAFE-001: activation proceeds when isSelfRecording returns false")
    func activationProceedsWhenNotSelfRecording() async throws {
        let provider = MockSelfRecordingStateProvider(recording: false)
        let detector = AudioSessionDetector(
            startDebounce: 0.05,
            stopDebounce: 0.05,
            selfRecordingProvider: provider,
            autoListen: false
        )
        let stream = detector.events()

        await detector.simulateActivation()
        try await Task.sleep(for: .milliseconds(200))

        var events: [MeetingDetectorEvent] = []
        for await event in stream {
            events.append(event)
            if events.count >= 1 { break }
        }

        #expect(
            events.contains(.meetingStarted(context: nil)),
            "SAFE-001: activation must emit meetingStarted when not self-recording"
        )
    }

    @Test("SAFE-001: nil provider does not suppress activation")
    func nilProviderDoesNotSuppress() async throws {
        let detector = AudioSessionDetector(
            startDebounce: 0.05,
            stopDebounce: 0.05,
            selfRecordingProvider: nil,
            autoListen: false
        )
        let stream = detector.events()

        await detector.simulateActivation()
        try await Task.sleep(for: .milliseconds(200))

        var events: [MeetingDetectorEvent] = []
        for await event in stream {
            events.append(event)
            if events.count >= 1 { break }
        }

        #expect(
            events.contains(.meetingStarted(context: nil)),
            "SAFE-001: nil provider must not suppress activation"
        )
    }

    // MARK: - REL-003: Device registration failure tolerance

    @Test("REL-003: detector operates normally after CoreAudio init (simulate still works)")
    func toleratesRegistrationFailure() async throws {
        // Even if CoreAudio enumeration silently finds no devices on CI,
        // simulateActivation must still work — the actor is fully operational.
        let detector = AudioSessionDetector(startDebounce: 0.05, stopDebounce: 0.05, autoListen: false)
        let stream = detector.events()

        await detector.simulateActivation()
        try await Task.sleep(for: .milliseconds(200))

        var events: [MeetingDetectorEvent] = []
        for await event in stream {
            events.append(event)
            if events.count >= 1 { break }
        }

        #expect(
            events.contains(.meetingStarted(context: nil)),
            "REL-003: simulateActivation must work even if CoreAudio registration found no devices"
        )
    }

    // MARK: - Backward compatibility

    @Test("backward compat: simulateActivation still works after CoreAudio changes")
    func simulateActivationBackwardCompat() async throws {
        let detector = AudioSessionDetector(startDebounce: 0.05, stopDebounce: 0.05, autoListen: false)
        let stream = detector.events()

        await detector.simulateActivation()
        try await Task.sleep(for: .milliseconds(200))

        var events: [MeetingDetectorEvent] = []
        for await event in stream {
            events.append(event)
            if events.count >= 1 { break }
        }

        #expect(events.contains(.meetingStarted(context: nil)))
    }

    @Test("backward compat: simulateDeactivation still works after CoreAudio changes")
    func simulateDeactivationBackwardCompat() async throws {
        let detector = AudioSessionDetector(startDebounce: 0.05, stopDebounce: 0.05, autoListen: false)
        let stream = detector.events()

        await detector.simulateActivation()
        try await Task.sleep(for: .milliseconds(150))
        await detector.simulateDeactivation()
        try await Task.sleep(for: .milliseconds(150))

        var events: [MeetingDetectorEvent] = []
        for await event in stream {
            events.append(event)
            if events.count >= 2 { break }
        }

        #expect(events.contains(.meetingStarted(context: nil)))
        #expect(events.contains(.meetingStopped))
    }
}

