import AudioInfrastructure
import Domain
import Foundation
@testable import MLInfrastructure
import Testing

// CalendarAwareMeetingDetector: hybrid detector composing CalendarEngine + AudioSessionDetector.
// Tests verify the core detection logic using injected fakes.

private func makeMeeting(
    id: String = "m1",
    title: String = "Stand-up",
    minutesFromNow: Double = 3,
    isAllDay: Bool = false
) -> CalendarMeeting {
    let start = Date().addingTimeInterval(minutesFromNow * 60)
    return CalendarMeeting(
        id: MeetingID(id),
        title: title,
        startDate: start,
        endDate: start.addingTimeInterval(3600),
        attendees: [],
        isRecurring: false,
        isAllDay: isAllDay,
        videoCallURL: nil,
        location: nil,
        organizer: nil,
        calendarName: nil,
        calendarSource: .local
    )
}

@Suite("CalendarAwareMeetingDetector")
struct CalendarAwareMeetingDetectorTests {
    // MARK: - FUNC-012: armed + audio → instant meetingStarted (no debounce)

    @Test("armed state + audio activation emits meetingStarted with .calendar trigger immediately")
    func armedPlusAudioNoDebounce() async throws {
        let calendar = MockCalendarEngine()
        // Meeting starts in 3 minutes — within the 5-min arm window
        let meeting = makeMeeting(minutesFromNow: 3)
        await calendar.setMeetings([meeting])

        let audioDetector = AudioSessionDetector(startDebounce: 10.0, stopDebounce: 10.0, autoListen: false)
        let config = MeetingDetectionConfig(
            startDebounce: 10.0,
            stopDebounce: 10.0,
            armWindow: 600.0,
            graceWindow: 5.0,
            armTimeout: 900.0
        )

        let detector = CalendarAwareMeetingDetector(
            calendar: calendar,
            audioDetector: audioDetector,
            config: config
        )
        let stream = detector.events()

        // Load calendar and arm
        try await Task.sleep(for: .milliseconds(100))

        // Trigger audio — armed state → should emit immediately (no 10s debounce)
        await audioDetector.simulateActivation()
        try await Task.sleep(for: .milliseconds(200))

        var events: [MeetingDetectorEvent] = []
        for await event in stream {
            events.append(event)
            if events.count >= 1 { break }
        }

        guard case let .meetingStarted(context) = events.first else {
            Issue.record("Expected meetingStarted, got: \(events)")
            return
        }
        #expect(context?.triggerSource == .calendar)
        #expect(context?.calendarMeeting?.id == meeting.id)
    }

    // MARK: - FUNC-013: unarmed + audio → debounced meetingStarted

    @Test("unarmed + audio activation emits meetingStarted with .audioOnly after debounce")
    func unarmedPlusAudioDebounced() async throws {
        let calendar = MockCalendarEngine()
        // No upcoming meetings → detector stays unarmed
        await calendar.setMeetings([])

        let audioDetector = AudioSessionDetector(startDebounce: 0.05, stopDebounce: 0.05, autoListen: false)
        let config = MeetingDetectionConfig(
            startDebounce: 0.05,
            stopDebounce: 0.05,
            armWindow: 300.0,
            graceWindow: 5.0,
            armTimeout: 900.0
        )

        let detector = CalendarAwareMeetingDetector(
            calendar: calendar,
            audioDetector: audioDetector,
            config: config
        )
        let stream = detector.events()

        try await Task.sleep(for: .milliseconds(50))
        await audioDetector.simulateActivation()
        try await Task.sleep(for: .milliseconds(200))

        var events: [MeetingDetectorEvent] = []
        for await event in stream {
            events.append(event)
            if events.count >= 1 { break }
        }

        guard case let .meetingStarted(context) = events.first else {
            Issue.record("Expected meetingStarted, got: \(events)")
            return
        }
        #expect(context?.triggerSource == .audioOnly)
        #expect(context?.calendarMeeting == nil)
    }

    // MARK: - FUNC-014 / SAFE-003: all-day events never armed

    @Test("all-day event is never entered into armed state")
    func allDayNeverArmed() async throws {
        let calendar = MockCalendarEngine()
        let allDayMeeting = makeMeeting(minutesFromNow: 1, isAllDay: true)
        await calendar.setMeetings([allDayMeeting])

        let audioDetector = AudioSessionDetector(startDebounce: 0.05, stopDebounce: 0.05, autoListen: false)
        let config = MeetingDetectionConfig(
            startDebounce: 0.05,
            stopDebounce: 0.05,
            armWindow: 600.0,
            graceWindow: 5.0,
            armTimeout: 900.0
        )

        let detector = CalendarAwareMeetingDetector(
            calendar: calendar,
            audioDetector: audioDetector,
            config: config
        )
        let stream = detector.events()

        try await Task.sleep(for: .milliseconds(100))
        await audioDetector.simulateActivation()
        try await Task.sleep(for: .milliseconds(200))

        var events: [MeetingDetectorEvent] = []
        for await event in stream {
            events.append(event)
            if events.count >= 1 { break }
        }

        // Should still emit meetingStarted but as .audioOnly (all-day not armed)
        guard case let .meetingStarted(context) = events.first else {
            Issue.record("Expected meetingStarted")
            return
        }
        #expect(context?.triggerSource == .audioOnly, "All-day event must not arm the detector")
        #expect(context?.calendarMeeting == nil, "All-day event must not populate calendarMeeting")
    }

    // MARK: - REL-001: calendar unavailable falls back to audio-only

    @Test("calendar error causes fallback to audio-only detection")
    func calendarDeniedFallsBackToAudio() async throws {
        let calendar = MockCalendarEngine()
        await calendar.setErrorToThrow(CalendarError.accessDenied)

        let audioDetector = AudioSessionDetector(startDebounce: 0.05, stopDebounce: 0.05, autoListen: false)
        let config = MeetingDetectionConfig(
            startDebounce: 0.05,
            stopDebounce: 0.05,
            armWindow: 300.0,
            graceWindow: 5.0,
            armTimeout: 900.0
        )

        let detector = CalendarAwareMeetingDetector(
            calendar: calendar,
            audioDetector: audioDetector,
            config: config
        )
        let stream = detector.events()

        try await Task.sleep(for: .milliseconds(100))
        await audioDetector.simulateActivation()
        try await Task.sleep(for: .milliseconds(200))

        var events: [MeetingDetectorEvent] = []
        for await event in stream {
            events.append(event)
            if events.count >= 1 { break }
        }

        // Calendar error → falls back to audio-only, still emits meetingStarted
        #expect(!events.isEmpty, "Should still emit meetingStarted even when calendar is unavailable")
        if case let .meetingStarted(context) = events.first {
            #expect(context?.triggerSource == .audioOnly)
        }
    }

    // MARK: - Protocol conformance

    @Test("CalendarAwareMeetingDetector conforms to MeetingDetector")
    func conformsToMeetingDetector() {
        let calendar = MockCalendarEngine()
        let audioDetector = AudioSessionDetector(autoListen: false)
        let detector = CalendarAwareMeetingDetector(
            calendar: calendar,
            audioDetector: audioDetector,
            config: MeetingDetectionConfig()
        )
        let _: any MeetingDetector = detector
    }
}

// MARK: - Slice C: C1 — makeStream() at init

/// RED: AsyncStream closure contains Task{} today. Must be absent after fix.
extension CalendarAwareMeetingDetectorTests {
    private func source() throws -> String {
        let thisFile = URL(fileURLWithPath: #filePath)
        let repoRoot = thisFile
            .deletingLastPathComponent().deletingLastPathComponent()
            .deletingLastPathComponent().deletingLastPathComponent()
            .deletingLastPathComponent()
        return try String(
            contentsOfFile: repoRoot
                .appendingPathComponent("Sources/Infrastructure/Calendar/CalendarAwareMeetingDetector.swift").path,
            encoding: .utf8
        )
    }

    @Test func `events uses makeStream not Task-in-closure`() throws {
        let src = try source()
        #expect(!src.contains("Task { await self.setContinuation"), "events() must use makeStream() at init, not Task-in-closure")
    }

    @Test func `CalendarAwareMeetingDetector has makeStream call`() throws {
        let src = try source()
        #expect(src.contains("makeStream"), "CalendarAwareMeetingDetector must store stream via makeStream()")
    }
}

