import Domain
import DuckDB
import Foundation

public extension DuckDBWriterActor {
    /// Persists a batch of InferenceMetrics entries to the inference_telemetry table.
    /// Skips entries that already exist (idempotent by id = modelId + timestamp).
    func recordTelemetry(_ entries: [InferenceMetrics]) throws {
        guard !entries.isEmpty else { return }
        do {
            let stmt = try prepared(DuckDBSQL.insertTelemetry)
            for entry in entries {
                let id = "\(entry.modelId.rawValue)-\(entry.timestamp.timeIntervalSince1970)"
                try stmt.bind(id, at: 1)
                try stmt.bind(entry.timestamp.ISO8601Format(), at: 2)
                try stmt.bind(entry.modelId.rawValue, at: 3)
                try stmt.bind(entry.audioDuration, at: 4)
                try stmt.bind(entry.inferenceDuration, at: 5)
                try stmt.bind(entry.realTimeFactor, at: 6)
                try stmt.bind(entry.confidence, at: 7)
                try stmt.bind(Int32(entry.sampleCount), at: 8)
                try stmt.bind(entry.computeUnit.rawValue, at: 9)
                try stmt.bind(entry.processMetrics?.processCpuUtilization, at: 10)
                let memMB = entry.processMetrics.map { Int64($0.processMemoryUsage / 1_048_576) }
                try stmt.bind(memMB, at: 11)
                let gpuMB = entry.processMetrics.map { Int64($0.processMlxMemoryUsage / 1_048_576) }
                try stmt.bind(gpuMB, at: 12)
                try stmt.bind(entry.processMetrics.map { Int32($0.processPageFaults) }, at: 13)
                try stmt.bind(entry.environmentMetrics?.osVersion, at: 14)
                try stmt.bind(entry.environmentMetrics?.cpuBrandString, at: 15)
                try stmt.bind(entry.environmentMetrics.map { Int32($0.physicalMemoryMB) }, at: 16)
                try stmt.bind(entry.environmentMetrics?.thermalState, at: 17)
                try stmt.bind(entry.environmentMetrics.flatMap { $0.isPluggedIn }, at: 18)
                try stmt.bind(entry.environmentMetrics.map { Int32($0.batteryStartPercentage) }, at: 19)
                _ = try stmt.execute()
            }
        } catch {
            throw StorageError.writeFailed(underlying: error)
        }
    }
}

import Domain
import Foundation
import IOKit.ps
import Logging
import Utilities

/// Actor that accumulates inference performance metrics in memory.
///
/// Thread-safe by actor isolation. Entries are stored in arrival order.
/// Use ``recentMetrics(limit:)`` to retrieve the most recent entries and
/// ``averageRTF(forModel:)`` to compute per-model performance summaries.
public actor InferenceTelemetry: InferenceMetricsRecorder {
    private var metrics: [InferenceMetrics] = []
    private let maxEntries: Int
    private let poller: SystemHardwarePollerProtocol?
    private let logger = AppLogger.for(category: "InferenceTelemetry")

    /// Creates a new telemetry store.
    ///
    /// - Parameter maxEntries: Maximum number of entries retained in memory.
    ///   When the limit is reached, the oldest entry is evicted (FIFO).
    ///   Defaults to 1000, which bounds memory growth for long meetings.
    public init(maxEntries: Int = 1000, poller: SystemHardwarePollerProtocol? = nil) {
        self.maxEntries = maxEntries
        self.poller = poller
    }

    /// Appends an inference metrics entry, evicting the oldest if the cap is reached.
    public func record(_ entry: InferenceMetrics) async {
        var enrichedEntry = entry

        if let poller {
            let processMemory = await poller.getResidentMemoryMB()
            let pageFaults = await poller.getPageFaults()
            let mlxMemory = await poller.getMlxMemoryUsageBytes()
            // We use 0.0 for cpu utilization for now as captureCpuSnapshot deals with deltas
            let cpuUtilization = 0.0 

            enrichedEntry.processMetrics = ProcessMetrics(
                processCpuUtilization: cpuUtilization,
                processMemoryUsage: processMemory * 1024 * 1024,
                processMlxMemoryUsage: mlxMemory,
                processPageFaults: pageFaults
            )

            let osVersion = await poller.getOSVersion()
            let cpuBrand = await poller.getCPUBrand()
            let physicalMemory = await poller.getPhysicalMemoryMB()
            let battery = await poller.getBatteryPercentage()
            let thermal = await poller.getThermalState()

            enrichedEntry.environmentMetrics = EnvironmentMetrics(
                osVersion: osVersion,
                cpuBrandString: cpuBrand,
                physicalMemoryMB: physicalMemory,
                batteryStartPercentage: battery,
                batteryEndPercentage: battery,
                isPluggedIn: Self.queryIsPluggedIn(),
                thermalState: thermal
            )
        }

        if metrics.count >= maxEntries {
            metrics.removeFirst()
        }
        metrics.append(enrichedEntry)
        logger.debug(
            "Recorded metrics for '\(entry.modelId, privacy: .public)' RTF=\(entry.realTimeFactor, privacy: .public)"
        )
    }

    /// Returns the most recent entries (newest last), capped at `limit`.
    ///
    /// - Parameter limit: Maximum number of entries to return. Defaults to 10.
    public func recentMetrics(limit: Int = 10) -> [InferenceMetrics] {
        let start = max(0, metrics.count - limit)
        return Array(metrics[start...])
    }

    /// Returns the mean real-time factor across all recorded entries for `modelId`,
    /// or `nil` if no entries have been recorded for that model.
    public func averageRTF(forModel modelId: ModelID) -> Double? {
        let filtered = metrics.filter { $0.modelId == modelId }
        guard !filtered.isEmpty else { return nil }
        let sum = filtered.reduce(0.0) { $0 + $1.realTimeFactor }
        return sum / Double(filtered.count)
    }

    /// Flushes all accumulated metrics to DuckDB and clears the in-memory buffer.
    /// Buffer is only cleared if the write succeeds — preserved on error for retry.
    public func flushToDuckDB(_ writer: DuckDBWriterActor) async throws {
        guard !metrics.isEmpty else { return }
        let toFlush = metrics
        try await writer.recordTelemetry(toFlush)
        metrics.removeAll()
        logger.info("Flushed \(toFlush.count, privacy: .public) telemetry entries to DuckDB")
    }

    // MARK: - Power State

    /// Queries IOKit for the actual AC/battery power state.
    /// Returns `nil` if IOKit is unavailable or reports no power sources.
    private static func queryIsPluggedIn() -> Bool? {
        guard let psInfo = IOPSCopyPowerSourcesInfo()?.takeRetainedValue(),
              let psList = IOPSCopyPowerSourcesList(psInfo)?.takeRetainedValue() as? [CFTypeRef],
              !psList.isEmpty else {
            return nil
        }
        for ps in psList {
            guard let desc = IOPSGetPowerSourceDescription(psInfo, ps)?.takeUnretainedValue() as? [String: Any],
                  let state = desc[kIOPSPowerSourceStateKey] as? String else {
                continue
            }
            return state == kIOPSACPowerValue
        }
        return nil
    }
}

