            audioDetector: audioDetector,
            config: config
        )
        let stream = detector.events()

        try await Task.sleep(for: .milliseconds(50))  // let calendar load
        await audioDetector.simulateActivation()
        let events = try await waitForEvents(stream, count: 1, timeout: .seconds(2))

        guard case let .meetingStarted(context) = events.first else {
            Issue.record("Expected meetingStarted, got: \(events)")
            return
        }
        #expect(context?.triggerSource == .audioOnly)
        #expect(context?.calendarMeeting == nil)
    }

    // MARK: - FUNC-014 / SAFE-003: all-day events never armed

    @Test("all-day event is never entered into armed state")
    func allDayNeverArmed() async throws {
        let calendar = MockCalendarEngine()
        let allDayMeeting = makeMeeting(minutesFromNow: 1, isAllDay: true)
        await calendar.setMeetings([allDayMeeting])

        let audioDetector = AudioSessionDetector(startDebounce: 0.05, stopDebounce: 0.05, autoListen: false)
        let config = MeetingDetectionConfig(
