import Foundation
@testable import AudioInfrastructure
import Testing

@Suite("MeetingAppMonitor")
struct MeetingAppMonitorTests {
    // MARK: - Registry (LIVE-006)

    @Test("knownMeetingApps contains all 6 required bundle IDs")
    func knownMeetingAppsContainsAll() {
        let required: Set = [
            "us.zoom.xos",
            "com.microsoft.teams",
            "com.microsoft.teams2",
            "com.apple.FaceTime",
            "com.cisco.webexmeetingsapp",
            "com.slack.Slack",
        ]
        #expect(required.isSubset(of: MeetingAppMonitor.knownMeetingApps))
    }

    @Test("knownMeetingApps has exactly 6 entries")
    func knownMeetingAppsCount() {
        #expect(MeetingAppMonitor.knownMeetingApps.count == 6)
    }

    // MARK: - MeetingAppEvent Equatability

    @Test("MeetingAppEvent.launched is Equatable")
    func launchedEquatable() {
        let a = MeetingAppEvent.launched(bundleId: "us.zoom.xos", name: "Zoom")
        let b = MeetingAppEvent.launched(bundleId: "us.zoom.xos", name: "Zoom")
        #expect(a == b)
    }

    @Test("MeetingAppEvent.terminated is Equatable")
    func terminatedEquatable() {
        let a = MeetingAppEvent.terminated(bundleId: "us.zoom.xos")
        let b = MeetingAppEvent.terminated(bundleId: "us.zoom.xos")
        #expect(a == b)
    }

    @Test("MeetingAppEvent.launched != .terminated")
    func launchedNotEqualTerminated() {
        let launched = MeetingAppEvent.launched(bundleId: "us.zoom.xos", name: "Zoom")
        let terminated = MeetingAppEvent.terminated(bundleId: "us.zoom.xos")
        #expect(launched != terminated)
    }

    // MARK: - events() returns AsyncStream

    @Test("events() returns AsyncStream<MeetingAppEvent>")
    func eventsReturnsAsyncStream() {
        let monitor = MeetingAppMonitor()
        let stream: AsyncStream<MeetingAppEvent> = monitor.events()
        // Just verify we can get an iterator — don't consume (would block)
        var iterator = stream.makeAsyncIterator()
        _ = iterator // silence unused warning
        _ = iterator
    }

    // MARK: - Simulate methods

    // Pattern: get stream first, await continuation setup, simulate, then iterate.
    // AsyncStream buffers the yielded event so the for-await sees it immediately.

    @Test("simulateLaunch emits .launched event")
    func simulateLaunchEmitsEvent() async throws {
        let monitor = MeetingAppMonitor()
        let stream = monitor.events()
        // Allow the internal Task { await setContinuation } to complete
        try await Task.sleep(for: .milliseconds(10))
        await monitor.simulateLaunch(bundleId: "us.zoom.xos", name: "Zoom")

        var received: MeetingAppEvent?
        for await event in stream {
            received = event
            break
        }

        #expect(received == .launched(bundleId: "us.zoom.xos", name: "Zoom"))
    }

    @Test("simulateTermination emits .terminated event")
    func simulateTerminationEmitsEvent() async throws {
        let monitor = MeetingAppMonitor()
        let stream = monitor.events()
        try await Task.sleep(for: .milliseconds(10))
        await monitor.simulateTermination(bundleId: "com.microsoft.teams")

        var received: MeetingAppEvent?
        for await event in stream {
            received = event
            break
        }

        #expect(received == .terminated(bundleId: "com.microsoft.teams"))
    }
}

// MARK: - Slice C: C1 — makeStream() at init

extension MeetingAppMonitorTests {
    private func source() throws -> String {
        let r = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent()
            .deletingLastPathComponent().deletingLastPathComponent()
            .deletingLastPathComponent()
        return try String(
            contentsOfFile: r
                .appendingPathComponent("Sources/Infrastructure/Audio/MeetingAppMonitor.swift").path,
            encoding: .utf8
        )
    }

    @Test func `MeetingAppMonitor events uses makeStream not Task-in-closure`() throws {
        let src = try source()
        #expect(!src.contains("Task { await self.setContinuation"), "events() must use makeStream() at init")
    }

    @Test func `MeetingAppMonitor has makeStream call`() throws {
        #expect(try source().contains("makeStream"), "MeetingAppMonitor must store stream via makeStream()")
    }
}

