let count = Int(frameSize)

// Prepend leftover samples from the previous call, then loop over full
// 256-sample chunks. Speex requires exactly frameSize samples per call;
// the chunking loop ensures every input sample is eventually processed.
//
// Offset-cursor avoids O(n²) Array.removeFirst shifts.
// farOffset advances in lockstep so each mic chunk gets the corresponding
// far-end window (not the same first 256 samples repeated every iteration).
let combined = remainder + mic.buffer.samples
let farSamples = farEnd.buffer.samples
var allProcessed: [Float] = []
allProcessed.reserveCapacity(combined.count)

var offset = 0
var farOffset = 0

while offset + count <= combined.count {
    fillInt16(&micInt16, from: Array(combined[offset ..< offset + count]), frameSize: count)
    let farSlice = farOffset < farSamples.count
        ? Array(farSamples[farOffset ..< min(farOffset + count, farSamples.count)])
        : []
    fillInt16(&farInt16, from: farSlice, frameSize: count)
    for i in 0 ..< count { outInt16[i] = 0 }

    speex_echo_cancellation(res.echo, &micInt16, &farInt16, &outInt16)
    speex_preprocess_run(res.pp, &outInt16)

    fillFloat32(&outFloat, from: outInt16)
    allProcessed.append(contentsOf: outFloat)

    offset += count
    farOffset += count
}

// Carry sub-frame leftovers into the next call.
remainder = Array(combined[offset...])

let outBuffer = AudioBuffer(
    sampleRate: Double(sampleRate),
    channelCount: 1,
    samples: allProcessed,
    timestamp: mic.buffer.timestamp
)
return TaggedAudioBuffer(buffer: outBuffer, track: .microphone, timestamp: mic.timestamp)

