import AudioToolbox
import AVFAudio
import AVFoundation
import CoreAudio
import Darwin
import Domain
import Foundation
import Logging
import Utilities

typealias DomainAudioBuffer = Domain.AudioBuffer

// MARK: - CoreAudioResources

/// Owns the live Core Audio tap and aggregate device IDs so they are destroyed
/// deterministically in `deinit` — even if `stop()` is never called on the actor.
///
/// Mirrors the `SpeexResources` pattern in `AECProcessorActor`.
final class CoreAudioResources {
    var tapID: AudioObjectID = .init(kAudioObjectUnknown)
    var aggregateDeviceID: AudioObjectID = .init(kAudioObjectUnknown)

    deinit {
        if aggregateDeviceID != kAudioObjectUnknown {
            AudioHardwareDestroyAggregateDevice(aggregateDeviceID)
        }
        if tapID != kAudioObjectUnknown {
            AudioHardwareDestroyProcessTap(tapID)
        }
    }
}

// MARK: - CoreAudioTapCaptureActor

public actor CoreAudioTapCaptureActor: AudioCaptureEngine, SelfRecordingStateProvider {
    private let audioQueue = DispatchSerialQueue(label: "app.the-record.coreaudio", qos: .userInitiated)
    public nonisolated var unownedExecutor: UnownedSerialExecutor {
        audioQueue.asUnownedSerialExecutor()
    }

    public nonisolated let recordingDirectory: URL

    // These members are internal (not private) to allow CoreAudioTapCaptureActorSupport.swift
    // to access them via cross-file extension. Actor isolation is the actual safety boundary —
    // all access goes through the actor's serial executor regardless of Swift access level.
    // TODO(5.8): Resolve via module-level access control when Infrastructure becomes its own SwiftPM target.
    var state: AudioCaptureState = .idle
    /// Core Audio tap and aggregate device IDs. Destroyed in `CoreAudioResources.deinit`
    /// as a safety net if `stop()` is never called.
    let resources = CoreAudioResources()
    var engine: AVAudioEngine?
    var wavWriter: WAVWriter?
    var sessionID: RecordingID?
    var sessionFileURL: URL?
    var sessionStartDate: Date?
    var sessionConfiguration: AudioConfiguration?
    var streamContinuation: AsyncStream<DomainAudioBuffer>.Continuation?
    let converterFailureThreshold = 5

    let targets: [AudioTapTarget]
    let tapAllAudio: Bool
    let outputDeviceUID: String?
    let logger = AppLogger.for(category: "CoreAudioTap")

    public init(
        recordingDirectory: URL,
        targets: [AudioTapTarget] = AudioTapTarget.defaults,
        tapAllAudio: Bool = false,
        outputDeviceUID: String? = nil
    ) {
        self.recordingDirectory = recordingDirectory
        self.targets = targets
        self.tapAllAudio = tapAllAudio
        self.outputDeviceUID = outputDeviceUID
    }

    // MARK: - AudioCaptureEngine

    // swiftlint:disable:next function_body_length
    public func start(sessionID: RecordingID, configuration: AudioConfiguration) async throws -> AudioBufferStream {
        guard state == .idle else { throw AudioError.captureFailed(underlying: nil) }

        // Permission probe — before state change or resource allocation (finding #21).
        // defaultOutputDeviceUID() failure means audio is non-functional; stay .idle.
        let outputUID = try outputDeviceUID ?? Self.defaultOutputDeviceUID()
        try Self.ensureAudioTapAccess(outputDeviceUID: outputUID)

        state = .starting
        // Guard against WAVWriter init or pre-do-block failures leaving state = .starting
        // permanently (blocking all future start() calls). The do-catch below handles
        // failures inside the do block; this defer handles everything before it.
        defer { if state == .starting { state = .idle } }

        let fileURL = makeFileURL(for: Date())
        try Directories.ensureDirectory(at: fileURL.deletingLastPathComponent())

        let writer = try WAVWriter(
            url: fileURL,
            sampleRate: Int(configuration.sampleRate),
            channels: configuration.channels
        )
        let (stream, continuation) = AsyncStream<DomainAudioBuffer>
            .makeStream(bufferingPolicy: .bufferingNewest(100))

        do {
            logger.info("Output device UID: \(outputUID, privacy: .private)")

            let tapUUID = UUID()

            // Compute once — used by both the isGlobalTap determination and tapDesc.bundleIDs.
            let matchedBundleIDs = tapAllAudio
                ? [String]()
                : await MainActor.run { ProcessMatcher.matchingBundleIDs(for: targets) }

            let isGlobalTap = resolveGlobalTap(matchedBundleIDs: matchedBundleIDs)
            let tapDesc = buildTapDescription(
                isGlobalTap: isGlobalTap,
                matchedBundleIDs: matchedBundleIDs,
                configuration: configuration,
                tapUUID: tapUUID,
                outputUID: outputUID
            )

            var tapObjectID: AudioObjectID = .init(kAudioObjectUnknown)
            let tapStatus = AudioHardwareCreateProcessTap(tapDesc, &tapObjectID)
            guard tapStatus == noErr else {
                let fourCC = String(bytes: withUnsafeBytes(of: tapStatus.bigEndian) { Array($0) }, encoding: .ascii) ??
                    "????"
                logger
                    .error(
                        // swiftlint:disable:next line_length
                        "AudioHardwareCreateProcessTap failed: \(tapStatus, privacy: .private) ('\(fourCC, privacy: .public)')"
                    )
                if tapStatus == 0x2161_7574 || tapStatus < 0 || tapStatus == kAudioHardwareNotRunningError {
                    throw AudioError
                        .permissionDenied(
                            // swiftlint:disable:next line_length
                            message: "System Audio Recording. Open System Settings > Privacy & Security > System Audio Recording Only and enable THE RECORD."
                        )
                }
                throw AudioError.captureFailed(underlying: NSError(domain: NSOSStatusErrorDomain, code: Int(tapStatus)))
            }
            resources.tapID = tapObjectID

            try await setupAggregateAndEngine(
                sessionID: sessionID,
                tapUUID: tapUUID,
                configuration: configuration,
                continuation: continuation,
                writer: writer
            )

            wavWriter = writer
            streamContinuation = continuation
            self.sessionID = sessionID
            sessionFileURL = fileURL
            sessionStartDate = Date()
            sessionConfiguration = configuration
            state = .recording

            logger.info("Core Audio Tap started — session=\(sessionID, privacy: .private)")
            return AudioBufferStream(id: sessionID, stream: stream, fileURL: fileURL, configuration: configuration)

        } catch {
            continuation.finish()
            state = .idle
            cleanup()
            logger.error("Failed to start Core Audio Tap: \(error, privacy: .private)")
            throw error
        }
    }

    /// Determines whether a global tap is needed, logging the reason.
    private func resolveGlobalTap(matchedBundleIDs: [String]) -> Bool {
        if tapAllAudio {
            logger.info("Creating global tap (tapAllAudio=true)")
            return true
        } else if matchedBundleIDs.isEmpty {
            logger.info("No matching meeting apps — creating global tap")
            return true
        } else {
            let bundleIDList = matchedBundleIDs.joined(separator: ",")
            logger.info("Targeting bundleIDs: \(bundleIDList, privacy: .public)")
            return false
        }
    }

    /// Constructs a configured `CATapDescription` for the given tap strategy.
    private nonisolated func buildTapDescription(
        isGlobalTap: Bool,
        matchedBundleIDs: [String],
        configuration: AudioConfiguration,
        tapUUID: UUID,
        outputUID: String
    ) -> CATapDescription {
        let tapDesc: CATapDescription
        if isGlobalTap {
            if configuration.channels == 1 {
                tapDesc = CATapDescription(monoGlobalTapButExcludeProcesses: [])
            } else {
                tapDesc = CATapDescription(stereoGlobalTapButExcludeProcesses: [])
            }
        } else if #available(macOS 26, *) {
            tapDesc = CATapDescription()
            tapDesc.bundleIDs = matchedBundleIDs
        } else {
            // macOS 15: bundleIDs targeting requires macOS 26 — fall back to global tap
            if configuration.channels == 1 {
                tapDesc = CATapDescription(monoGlobalTapButExcludeProcesses: [])
            } else {
                tapDesc = CATapDescription(stereoGlobalTapButExcludeProcesses: [])
            }
        }

        tapDesc.name = "THE RECORD System Audio"
        tapDesc.uuid = tapUUID
        tapDesc.isPrivate = true
        tapDesc.muteBehavior = .unmuted
        tapDesc.isMixdown = true
        tapDesc.isMono = configuration.channels == 1
        tapDesc.isExclusive = false
        tapDesc.deviceUID = outputUID
        tapDesc.stream = 0
        if #available(macOS 26, *) { tapDesc.isProcessRestoreEnabled = true }

        return tapDesc
    }

    public func stop() async throws -> AudioFile {
        guard state == .recording else {
            throw AudioError.captureFailed(underlying: nil)
        }
        state = .stopping
        // T014: guarantee state returns to .idle even if finalize() throws or
        // sessionFileURL is nil. Without this defer, any early throw left the
        // actor permanently at .stopping, blocking subsequent start() calls.
        defer { if state == .stopping { cleanup()
            state = .idle
        } }

        streamContinuation?.finish()

        // Teardown order: remove tap → clear device → stop engine → destroy aggregate → destroy tap
        if let engine {
            engine.inputNode.removeTap(onBus: 0)

            if let audioUnit = engine.inputNode.audioUnit {
                var unknownDevID: AudioObjectID = .init(kAudioObjectUnknown)
                AudioUnitSetProperty(
                    audioUnit,
                    kAudioOutputUnitProperty_CurrentDevice,
                    kAudioUnitScope_Global, 0,
                    &unknownDevID,
                    UInt32(MemoryLayout<AudioObjectID>.size)
                )
            }

            engine.stop()
            self.engine = nil
        }

        try await wavWriter?.finalize()

        guard let fileURL = sessionFileURL else {
            throw AudioError.captureFailed(underlying: nil)
        }
        let startDate = sessionStartDate ?? Date()
        let config = sessionConfiguration ?? AudioConfiguration()
        let duration = Date().timeIntervalSince(startDate)
        let fileSize = (try? FileManager.default.attributesOfItem(atPath: fileURL.path)[.size] as? Int64) ?? 0
        let sampleCount = Int(duration * config.sampleRate)

        cleanup()
        state = .idle

        let durationStr = String(format: "%.1f", duration)
        logger.info("Core Audio Tap stopped — duration=\(durationStr, privacy: .private)s")

        // Use the session ID that was passed to start() — INV-001: AudioFile.id == RecordingSession.id.
        // The fallback should never fire; if it does, the AudioFile.id will not match the
        // RecordingSession.id and any downstream join by ID will silently fail.
        if sessionID == nil {
            logger.error("stop() called with nil sessionID — INV-001 violated: AudioFile.id will not match RecordingSession.id")
        }
        let fileID = sessionID ?? RecordingID.generate()
        return AudioFile(
            id: fileID,
            url: fileURL,
            recordedAt: startDate,
            duration: duration,
            fileSize: fileSize,
            configuration: config,
            sampleCount: sampleCount
        )
    }

    public func isRecording() -> Bool {
        state == .recording
    }

    public func isSelfRecording() async -> Bool {
        state == .recording
    }
}

