// Offset-cursor avoids O(n²) Array.removeFirst shifts.
// far-end start = max(0, offset - remCount): combined[0..remCount-1] is remainder with no current-call far-end.
let combined = remainder + mic.buffer.samples
let farSamples = farEnd.buffer.samples
let remCount = remainder.count
var allProcessed: [Float] = []
allProcessed.reserveCapacity(combined.count)

var offset = 0

while offset + count <= combined.count {
    fillInt16(&micInt16, from: Array(combined[offset ..< offset + count]), frameSize: count)
    let rawFarStart = offset - remCount
    let farSlice: [Float]
    if rawFarStart >= farSamples.count {
        // Far-end exhausted (capture-size mismatch) — repeat last valid window rather than zeros.
        let lastStart = max(0, farSamples.count - count)
        farSlice = farSamples.isEmpty ? [] : Array(farSamples[lastStart ..< min(lastStart + count, farSamples.count)])
    } else {
        let clampedStart = max(0, rawFarStart)
        farSlice = Array(farSamples[clampedStart ..< min(clampedStart + count, farSamples.count)])
    }
    fillInt16(&farInt16, from: farSlice, frameSize: count)
    for i in 0 ..< count { outInt16[i] = 0 }

    speex_echo_cancellation(res.echo, &micInt16, &farInt16, &outInt16)
    speex_preprocess_run(res.pp, &outInt16)

    fillFloat32(&outFloat, from: outInt16)
    allProcessed.append(contentsOf: outFloat)

    offset += count
}

